static void stein(double breite) {
    Turtle.forward(breite);
    Turtle.turnLeft(90);
    Turtle.forward(20);
    Turtle.turnLeft(90);
    Turtle.forward(breite);
    Turtle.turnLeft(90);
    Turtle.forward(20);
    Turtle.turnLeft(90);
}

static void linie(double laenge) {
    Turtle.forward(laenge);
    Turtle.penUp();
    Turtle.forward(-laenge);
    Turtle.penDown();
}

static void nachRechts(double a) {
    Turtle.penUp();
    Turtle.forward(a);
    Turtle.penDown();
}

static void nachLinks(double a) {
    Turtle.penUp();
    Turtle.forward(-a);
    Turtle.penDown();
}

static void nachOben(double a) {
    Turtle.penUp();
    Turtle.turnLeft(90);
    Turtle.forward(a);
    Turtle.turnRight(90);
    Turtle.penDown();
}

static void nachUnten(double a) {
    Turtle.penUp();
    Turtle.turnRight(90);
    Turtle.forward(a);
    Turtle.turnLeft(90);
    Turtle.penDown();
}
```

